// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        v1 = bound(v1, 1, 1e30);
        v2 = bound(v2, 0, 1e30);
        Attacker a = new Attacker(c);
        vm.deal(address(a), v1 + v2);
        a.run(v1, v2);
        // Reference: lock makes the re-entrant addToBalance during withdrawal revert,
        // so the withdrawal reverts and the balance stays at v1.
        // Mutant: re-entrant add succeeds, balance becomes v1+v2, then withdrawn -> 0 != v1.
        assertTrue(c.getBalance(address(a)) == v1);
    }
}

contract Attacker {
    Reentrance c;
    uint256 v2;
    constructor(Reentrance _c) { c = _c; }
    function run(uint256 v1, uint256 v2_) external {
        v2 = v2_;
        c.addToBalance{value: v1}();
        try c.withdrawBalance() {} catch {}
    }
    receive() external payable {
        c.addToBalance{value: v2}();
    }
}
